def colorstats(G):
    Bl=blocks(G); res=Counter()
    for (bi,bj),v in Bl.items():
        w=Bl.get((bi-2,bj+2))  # NE
        if w and 8 not in v and 8 not in w:
            tv,tw=typ(v),typ(w)
            if tv in ('AD','TT') and tw in ('AD','TT'):
                res[('ad', v[1]==w[1])]+=1
        w2=Bl.get((bi+2,bj+2))  # SE
        if w2 and 8 not in v and 8 not in w2:
            tv,tw=typ(v),typ(w2)
            if tv in ('MD','TT') and tw in ('MD','TT'):
                res[('md', v[0]==w2[0])]+=1
